CREATE TYPE "Role" AS ENUM ('OWNER','ADMIN','STAFF','VIEWER');
CREATE TYPE "ServerType" AS ENUM ('PAPER','VELOCITY','OTHER');
CREATE TYPE "ServerStatus" AS ENUM ('ONLINE','OFFLINE','DEGRADED');
CREATE TYPE "AlertSeverity" AS ENUM ('CRITICAL','WARNING','INFO');
CREATE TYPE "AlertCategory" AS ENUM ('SECURITY','PERFORMANCE','SERVER','PLAYER','NETWORK');
CREATE TYPE "ConsoleCategory" AS ENUM ('SERVER','COMMAND','SECURITY','PERFORMANCE','PLAYER','PLUGIN','ERROR');
CREATE TYPE "RemoteCommandStatus" AS ENUM ('PENDING','SENT','EXECUTED','FAILED','BLOCKED','EXPIRED');
CREATE TYPE "CommandPolicyAction" AS ENUM ('BLOCK','ALERT_ONLY','REQUIRE_CONFIRMATION','ALLOW');
CREATE TABLE "Workspace" ("id" TEXT NOT NULL PRIMARY KEY,"name" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "User" ("id" TEXT NOT NULL PRIMARY KEY,"workspaceId" TEXT NOT NULL,"username" TEXT NOT NULL,"email" TEXT NOT NULL,"displayName" TEXT NOT NULL,"passwordHash" TEXT NOT NULL,"role" "Role" NOT NULL DEFAULT 'VIEWER',"disabledAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "User_workspaceId_fkey" FOREIGN KEY ("workspaceId") REFERENCES "Workspace"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE UNIQUE INDEX "User_username_key" ON "User"("username"); CREATE UNIQUE INDEX "User_email_key" ON "User"("email");
CREATE TABLE "UserSession" ("id" TEXT NOT NULL PRIMARY KEY,"userId" TEXT NOT NULL,"refreshHash" TEXT NOT NULL,"userAgent" TEXT,"ipAddress" TEXT,"expiresAt" TIMESTAMP(3) NOT NULL,"revokedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "UserSession_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE "DeviceToken" ("id" TEXT NOT NULL PRIMARY KEY,"userId" TEXT NOT NULL,"tokenHash" TEXT NOT NULL,"platform" TEXT NOT NULL,"enabled" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "DeviceToken_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE "Server" ("id" TEXT NOT NULL PRIMARY KEY,"workspaceId" TEXT NOT NULL,"displayName" TEXT NOT NULL,"type" "ServerType" NOT NULL DEFAULT 'PAPER',"status" "ServerStatus" NOT NULL DEFAULT 'OFFLINE',"lastSeenAt" TIMESTAMP(3),"version" TEXT,"address" TEXT,"agentPublicIdentity" TEXT,"panicMode" BOOLEAN NOT NULL DEFAULT false,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Server_workspaceId_fkey" FOREIGN KEY ("workspaceId") REFERENCES "Workspace"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE "AgentCredential" ("id" TEXT NOT NULL PRIMARY KEY,"serverId" TEXT NOT NULL,"publicIdentity" TEXT NOT NULL,"secretHash" TEXT NOT NULL,"pairingTokenHash" TEXT,"pairingExpiresAt" TIMESTAMP(3),"revokedAt" TIMESTAMP(3),"lastRotatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "AgentCredential_serverId_fkey" FOREIGN KEY ("serverId") REFERENCES "Server"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE "ServerMetric" ("id" TEXT NOT NULL PRIMARY KEY,"serverId" TEXT NOT NULL,"snapshot" JSONB NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "ServerMetric_serverId_fkey" FOREIGN KEY ("serverId") REFERENCES "Server"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE INDEX "ServerMetric_serverId_createdAt_idx" ON "ServerMetric"("serverId","createdAt");
CREATE TABLE "ServerLatestSnapshot" ("serverId" TEXT NOT NULL PRIMARY KEY,"snapshot" JSONB NOT NULL,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "ServerLatestSnapshot_serverId_fkey" FOREIGN KEY ("serverId") REFERENCES "Server"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE "Alert" ("id" TEXT NOT NULL PRIMARY KEY,"serverId" TEXT,"severity" "AlertSeverity" NOT NULL,"category" "AlertCategory" NOT NULL,"title" TEXT NOT NULL,"message" TEXT NOT NULL,"metadata" JSONB,"acknowledgedAt" TIMESTAMP(3),"acknowledgedBy" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "Alert_serverId_fkey" FOREIGN KEY ("serverId") REFERENCES "Server"("id") ON DELETE SET NULL ON UPDATE CASCADE);
CREATE INDEX "Alert_serverId_createdAt_idx" ON "Alert"("serverId","createdAt");
CREATE TABLE "ConsoleLog" ("id" TEXT NOT NULL PRIMARY KEY,"serverId" TEXT NOT NULL,"level" TEXT NOT NULL,"source" TEXT NOT NULL,"message" TEXT NOT NULL,"category" "ConsoleCategory" NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "ConsoleLog_serverId_fkey" FOREIGN KEY ("serverId") REFERENCES "Server"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE INDEX "ConsoleLog_serverId_createdAt_idx" ON "ConsoleLog"("serverId","createdAt");
CREATE TABLE "SecurityEvent" ("id" TEXT NOT NULL PRIMARY KEY,"serverId" TEXT NOT NULL,"type" TEXT NOT NULL,"actor" TEXT,"subject" TEXT,"action" TEXT NOT NULL,"metadata" JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "SecurityEvent_serverId_fkey" FOREIGN KEY ("serverId") REFERENCES "Server"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE INDEX "SecurityEvent_serverId_createdAt_idx" ON "SecurityEvent"("serverId","createdAt");
CREATE TABLE "AuditLog" ("id" TEXT NOT NULL PRIMARY KEY,"userId" TEXT,"serverId" TEXT,"action" TEXT NOT NULL,"target" TEXT,"metadata" JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "AuditLog_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE SET NULL ON UPDATE CASCADE,CONSTRAINT "AuditLog_serverId_fkey" FOREIGN KEY ("serverId") REFERENCES "Server"("id") ON DELETE SET NULL ON UPDATE CASCADE);
CREATE INDEX "AuditLog_serverId_createdAt_idx" ON "AuditLog"("serverId","createdAt"); CREATE INDEX "AuditLog_userId_createdAt_idx" ON "AuditLog"("userId","createdAt");
CREATE TABLE "RemoteCommand" ("id" TEXT NOT NULL PRIMARY KEY,"serverId" TEXT NOT NULL,"userId" TEXT NOT NULL,"command" TEXT NOT NULL,"status" "RemoteCommandStatus" NOT NULL DEFAULT 'PENDING',"nonce" TEXT NOT NULL,"requestedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"sentAt" TIMESTAMP(3),"executedAt" TIMESTAMP(3),"result" TEXT,"error" TEXT,CONSTRAINT "RemoteCommand_serverId_fkey" FOREIGN KEY ("serverId") REFERENCES "Server"("id") ON DELETE CASCADE ON UPDATE CASCADE,CONSTRAINT "RemoteCommand_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE INDEX "RemoteCommand_serverId_requestedAt_idx" ON "RemoteCommand"("serverId","requestedAt");
CREATE TABLE "CommandPolicy" ("id" TEXT NOT NULL PRIMARY KEY,"serverId" TEXT NOT NULL,"command" TEXT NOT NULL,"action" "CommandPolicyAction" NOT NULL DEFAULT 'ALERT_ONLY',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "CommandPolicy_serverId_fkey" FOREIGN KEY ("serverId") REFERENCES "Server"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE UNIQUE INDEX "CommandPolicy_serverId_command_key" ON "CommandPolicy"("serverId","command");
CREATE TABLE "AllowedOp" ("id" TEXT NOT NULL PRIMARY KEY,"serverId" TEXT NOT NULL,"uuid" TEXT NOT NULL,"name" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "AllowedOp_serverId_fkey" FOREIGN KEY ("serverId") REFERENCES "Server"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE UNIQUE INDEX "AllowedOp_serverId_uuid_key" ON "AllowedOp"("serverId","uuid");
